  "statements": [
    {
      "text": "The control only allows recovering the tool changer when the 2066 tool changer fault alarm occurs.",
      "claim_ref": {
        "workflow_id": "REAL_WF_0003",
        "revision": 2,
        "entity_type": "claim",
        "entity_id": "REAL_WF_0003_CL_005"
      },
      "evidence_ids": [
